const pin = (name: string, actual: string): void => {
  assert.strictEqual(actual, GOLDEN[name]);
};

describe("the services panel, byte for byte", () => {
  it("1 not handed, sampled", () => {
    pin("1 not handed, sampled", servicesMarkup({}));
  });

  it("2 not handed, unsampled", () => {
    pin("2 not handed, unsampled", servicesMarkup({ diagnostics: neverBuilt }));
  });

  it("3 failed, sampled", () => {
    pin(
      "3 failed, sampled",
      servicesMarkup({
        reading: { wiring: WiringRead.Failed({ reason: "boom: layer refused" }) },
      }),
    );
  });

  it("4 failed, unsampled", () => {
    pin(
      "4 failed, unsampled",
      servicesMarkup({
        diagnostics: neverBuilt,
        reading: { wiring: WiringRead.Failed({ reason: "boom: layer refused" }) },
      }),
    );
  });

  it("5 nine rows, nothing read, sampled", () => {
    pin(
      "5 nine rows, nothing read, sampled",
      servicesMarkup({
        reading: { wiring: WiringRead.Read({ report: r9(ABSENT_CACHE) }), activity: NO_ACTIVITY },
      }),
    );
  });

  it("6 nine rows, unsampled", () => {
    pin(
      "6 nine rows, unsampled",
      servicesMarkup({
        diagnostics: neverBuilt,
        reading: { wiring: WiringRead.Read({ report: r9(ABSENT_CACHE) }), activity: NO_ACTIVITY },
      }),
    );
  });

  it("7 one activity entry, unsampled", () => {
    pin(
      "7 one activity entry, unsampled",
      servicesMarkup({
        diagnostics: neverBuilt,
        reading: {
          wiring: WiringRead.Read({ report: r9(ABSENT_CACHE) }),
          activity: ATTRIBUTE_ONLY,
        },
      }),
    );
  });

  it("8 every suffix and a sized cache", () => {
    pin(
      "8 every suffix and a sized cache",
      servicesMarkup({
        reading: { wiring: WiringRead.Read({ report: r9(SIZED_CACHE) }), activity: ACTIVITY },
      }),
    );
  });

  it("9 collected, none for any port", () => {
    pin(
      "9 collected, none for any port",
      servicesMarkup({
        reading: {
          wiring: WiringRead.Read({ report: r9(UNSIZED_CACHE) }),
          activity: NO_ACTIVITY,
          portCalls: logOf([]),
        },
      }),
    );
  });

  it("13 the first activity entry wins", () => {
    pin(
      "13 the first activity entry wins",
      servicesMarkup({
        reading: { wiring: WiringRead.Read({ report: r9(ABSENT_CACHE) }), activity: DUPLICATED },
      }),
    );
  });
});
